// Headless acceptance test for the robots' GPU RIG (robot-core.js) — a
// standalone script like composite-coherence.js, not a Playwright spec:
//
//   cd tests/e2e && bun rig-parity.js [baseURL=http://localhost:8098]
//
// The game draws its robots through the GPU rig: the skeleton runs in the
// vertex shader from a dozen per-instance pose scalars and the whole batch
// is ONE instanced draw. The CPU rig (JS builds a 27-mat4 palette per robot,
// one draw each) stays in robot-core as the single-sprite path AND as the
// reference: tools/rig-parity.html renders every pose x weapon x a spread of
// animation times / palettes / facings through both, in full 64-tile
// batches, and compares the art-resolution atlas texel by texel. Asserted:
//   1) the GPU rig is actually live (instancing available, no GL errors);
//   2) every tile holds a robot (no collapsed / off-tile geometry);
//   3) parity: the two rigs differ by at most a few edge texels per tile
//      (float32 shader trig vs float64 JS trig can flip a texel whose
//      centre sits on a box edge; anything structural — a wrong joint, a
//      weapon that failed to collapse, a spill into the neighbour tile —
//      moves dozens);
//   4) the CPU reference itself is unchanged (pinned checksum, SwiftShader
//      only — a different rasterizer legitimately hashes differently).
// The page is also the human-eye version: /tools/rig-parity.html (add
// ?bench=200 for the CPU submit cost of both rigs on the machine at hand).
const { chromium } = require('playwright');

const BASE = process.argv[2] || 'http://localhost:8098';
// Per-tile / total budget of differing texels (a tile is 43 x 43 = 1849).
const MAX_TILE_DIFF = 6;
const MAX_TOTAL_DIFF_PER_CASE = 0.5;
// FNV of the CPU-rig atlases under SwiftShader (headless Chromium). Update
// ONLY for an intended change of the robot art / rig.
const CPU_GOLDEN = process.env.RIG_GOLDEN || '';

(async () => {
  const browser = await chromium.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader', '--disable-dev-shm-usage'],
  });
  let failures = 0;
  const report = (ok, msg) => { console.log((ok ? 'PASS ' : 'FAIL ') + msg); if (!ok) failures++; };

  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
  page.on('pageerror', (e) => errors.push(String(e)));
  await page.goto(BASE + '/tools/rig-parity.html');
  await page.waitForFunction(() => window.rigParity && window.rigParity.done, null, { timeout: 60000 });
  const r = await page.evaluate(() => window.rigParity);

  console.log(`cases ${r.cases} · differing texels ${r.totalDiff} · worst tile ${r.maxTileDiff} · max channel delta ${r.maxChannelDiff}`);
  console.log(`cpu hash ${r.cpuHash} · gpu hash ${r.gpuHash}`);
  const worst = r.tiles.slice().sort((a, b) => b.diff - a.diff).slice(0, 5);
  for (const t of worst) console.log(`   ${String(t.diff).padStart(4)}  ${t.name}`);

  report(errors.length === 0, `no console / page errors${errors.length ? ': ' + errors.join(' | ') : ''}`);
  report(r.glErrors === 0, `no GL errors (${r.glErrors})`);
  report(r.gpuRig && r.instanced, 'the GPU rig is live (ANGLE_instanced_arrays)');
  report(r.cases >= 160, `covers every pose x weapon x time (${r.cases} cases)`);
  report(r.emptyTiles === 0, `every tile holds a robot (${r.emptyTiles} empty)`);
  report(r.maxTileDiff <= MAX_TILE_DIFF, `worst tile differs by ${r.maxTileDiff} texels (<= ${MAX_TILE_DIFF})`);
  report(r.totalDiff <= r.cases * MAX_TOTAL_DIFF_PER_CASE,
    `total differing texels ${r.totalDiff} (<= ${r.cases * MAX_TOTAL_DIFF_PER_CASE})`);
  if (CPU_GOLDEN) report(r.cpuHash === CPU_GOLDEN, `CPU reference checksum ${r.cpuHash} == pinned ${CPU_GOLDEN}`);

  await browser.close();
  if (failures) { console.log(`${failures} FAILED`); process.exit(1); }
  console.log('ALL PASS');
})().catch((e) => { console.error(e); process.exit(1); });

const BODY_CUBES = 14; // without the barrel; 15 with

/* ---------- the RIG: the skeleton's numbers, shared by BOTH rigs ----------
   The robot's skeleton exists twice, on purpose:
     - the CPU RIG (`_renderRobot`): JS walks the joint hierarchy with M4 and
       uploads one pose matrix per box (the 27-mat4 palette) — one draw per
       robot. It serves every single-sprite render (inspector, portrait /
       gun / head bakes, orbit cameras) and is the REFERENCE the GPU rig is
       tested against;
     - the GPU RIG (`rigVS`): the same hierarchy evaluated IN THE VERTEX
       SHADER from a dozen per-instance pose scalars, every robot of a batch
       in ONE instanced draw — what the game runs (see the GPU RIG section).
   Both read the joint pivots (`RIG`) and the per-box joint / offset / size
   table (`RIG_BOXES`) below, so the GEOMETRY lives once; what is mirrored is
   the ORDER OF ROTATIONS per joint chain (`_renderRobot`'s leg() / arm() vs
   rigVS's main()). tests/e2e/rig-parity.js renders every pose x weapon
   through both and compares them texel by texel — edit one rig, the test
   names the pose that diverged. */
const RIG = {
  hipX: 0.32, hipY: 0.6,            // hip pivots (left = -hipX)
  kneeY: -0.6, kneeBend: 0.6,       // knee below the hip; bend = max(0,-swing)*kneeBend
  shoulderX: 0.62, shoulderY: 1.5,  // shoulder pivots (left = -shoulderX)
  elbowY: -0.52,                    // elbow below the shoulder
  aim: -1.35,                       // the gun-hand's forward (aiming) shoulder pitch
  gripY: -0.42,                     // held weapon's grip anchor below the elbow
};
// Joint frames a box can hang from (rigid: rotation + translation, no scale).
const J_ROOT=0, J_LLEG=1, J_LSHIN=2, J_RLEG=3, J_RSHIN=4,
      J_LARM=5, J_LFORE=6, J_RARM=7, J_RFORE=8;
// Per body palette slot (same order as BODY_PART_TAGS): the joint the box
// hangs from, its centre in that joint's frame and its size.
const RIG_BOXES = [
  {j:J_ROOT,  t:[0, 1.15, 0   ], s:[0.9, 1.0, 0.55]},  // 0  torso
  {j:J_ROOT,  t:[0, 1.95, 0.02], s:[0.62,0.55,0.55]},  // 1  head
  {j:J_ROOT,  t:[0, 1.98, 0.28], s:[0.5, 0.16,0.08]},  // 2  visor strip
  {j:J_ROOT,  t:[0, 0.72, 0   ], s:[0.8, 0.3, 0.5 ]},  // 3  hips
  {j:J_LLEG,  t:[0,-0.28, 0   ], s:[0.3, 0.62,0.32]},  // 4  L thigh
  {j:J_LSHIN, t:[0,-0.28, 0   ], s:[0.26,0.6, 0.28]},  // 5  L shin
  {j:J_LSHIN, t:[0,-0.6,  0.06], s:[0.32,0.22,0.5 ]},  // 6  L foot
  {j:J_RLEG,  t:[0,-0.28, 0   ], s:[0.3, 0.62,0.32]},  // 7  R thigh
  {j:J_RSHIN, t:[0,-0.28, 0   ], s:[0.26,0.6, 0.28]},  // 8  R shin
  {j:J_RSHIN, t:[0,-0.6,  0.06], s:[0.32,0.22,0.5 ]},  // 9  R foot
  {j:J_LARM,  t:[0,-0.26, 0   ], s:[0.24,0.55,0.26]},  // 10 L upper arm
  {j:J_LFORE, t:[0,-0.24, 0   ], s:[0.2, 0.5, 0.22]},  // 11 L forearm
  {j:J_RARM,  t:[0,-0.26, 0   ], s:[0.24,0.55,0.26]},  // 12 R upper arm
  {j:J_RFORE, t:[0,-0.24, 0   ], s:[0.2, 0.5, 0.22]},  // 13 R forearm
  {j:J_RFORE, t:[0,-0.5,  0   ], s:[0.14,0.5, 0.14]},  // 14 bare-hand barrel
];
// the box's own local matrix (translate * scale), for the CPU rig
function rigBoxLocal(slot){
  const b = RIG_BOXES[slot];
  return M4.mul(M4.translate(b.t[0],b.t[1],b.t[2]), M4.scale(b.s[0],b.s[1],b.s[2]));
}

/* ---------- the GPU RIG: the skeleton in the vertex shader ----------
   The CPU rig costs, PER ROBOT PER FRAME, ~60 mat4 products in JS, a 432-float
   uniform upload and viewport + scissor + 1-2 draw calls. The GPU rig moves
   the joint hierarchy into the vertex shader instead:
     - the mesh (`buildRigMesh`) holds every box ANY robot can show — body,
       bare-hand barrel and ALL THREE held weapons — each vertex PRE-PLACED
       in its joint's frame (box offset + size baked in) and tagged with its
       joint and a VISIBILITY class; boxes this robot does not show (the
       weapons it does not hold, the barrel, a severed head) COLLAPSE to one
       off-clip point — degenerate triangles rasterize nothing (the trick the
       CPU rig's `headless` already used), so the vertex count is fixed and
       one draw serves every loadout;
     - a robot is 16 floats of per-INSTANCE data: its tile, facing, palette
       and posePlan()'s scalars (the pose LOGIC stays in JS: branchy scalar
       code, a few dozen flops). The shader walks the vertex's own joint
       chain — at most 5 rotations — for position and normal;
     - the tile is placed in the shader (clip-space offset into the batch
       target, one big viewport) and clipped by a fragment discard on the
       tile-local NDC — the per-pixel equivalent of the CPU path's per-tile
       scissor, so a sprawled body is cut at its tile edge exactly as before.
   => the whole batch is ONE bufferData + ONE drawArraysInstancedANGLE.
   Needs ANGLE_instanced_arrays (universal on WebGL 1); without it, or for a
   robot with a camera of its own (opts.orbit / opts.halfV), the batch falls
   back to the CPU rig per robot. 7 vertex attributes (WebGL 1 guarantees 8),
   4 + 29 + 1 vertex uniform vectors. */
const VIS_ALWAYS=0, VIS_HEAD=1, VIS_BARREL=2, VIS_WEAPON0=3; // weapon k (1..3) = VIS_WEAPON0 + k - 1
const RIG_PALS = 8;          // distinct palettes per instanced draw (more = an early flush)
const RIG_INST_FLOATS = 16;  // per-instance floats (4 vec4 attributes)
const glf = (x) => { const s = String(x); return /[.e]/.test(s) ? s : s + ".0"; };
const rigVS = `
attribute vec3 aPos;     // box vertex, pre-placed in its JOINT's frame
attribute vec3 aNormal;
attribute vec4 aExtra;   // x joint + 16*visibility class, y color sel, z accent sel, w part id
attribute vec4 aI0;      // per instance: tile col, tile row, facing (rad), palette index
attribute vec4 aI1;      //   bob, lean, zback, recoil
attribute vec4 aI2;      //   legA, legB, armLp, armRp
attribute vec4 aI3;      //   armRaise, armOut, elbow, flags = weapon + 4*forward + 8*headless
uniform mat4 uVP;
uniform vec3 uCol[${RIG_PALS*3 + 5}]; // RIG_PALS x (body, accent, trim), then the 5 fixed tones
uniform float uTileScale;             // 2 / batch columns
varying vec3 vN;
varying vec3 vColor;
varying vec3 vAccent;
varying float vId;
varying vec2 vLocal;                  // tile-local NDC (the fragment clip)
// the M4.rotX / rotY / rotZ conventions, applied to a point and its normal
void rotX(inout vec3 p, inout vec3 n, float a){
  float c = cos(a), s = sin(a);
  p = vec3(p.x, c*p.y - s*p.z, s*p.y + c*p.z);
  n = vec3(n.x, c*n.y - s*n.z, s*n.y + c*n.z);
}
void rotY(inout vec3 p, inout vec3 n, float a){
  float c = cos(a), s = sin(a);
  p = vec3(c*p.x + s*p.z, p.y, c*p.z - s*p.x);
  n = vec3(c*n.x + s*n.z, n.y, c*n.z - s*n.x);
}
void rotZ(inout vec3 p, inout vec3 n, float a){
  float c = cos(a), s = sin(a);
  p = vec3(c*p.x - s*p.y, s*p.x + c*p.y, p.z);
  n = vec3(c*n.x - s*n.y, s*n.x + c*n.y, n.z);
}
// color selector -> uCol index: 0-2 = this robot's palette, 3-7 = fixed tones
float colIdx(float sel, float pal){ return sel < 2.5 ? pal*3.0 + sel : ${glf(RIG_PALS*3 - 3)} + sel; }
void main(){
  float vis = floor((aExtra.x + 0.5) / 16.0);
  float joint = aExtra.x - vis*16.0;
  float fl = aI3.w;
  float headless = floor((fl + 0.5) / 8.0); fl -= headless*8.0;
  float forward = floor((fl + 0.5) / 4.0);
  float weapon = fl - forward*4.0;

  vN = vec3(0.0, 1.0, 0.0); vColor = vec3(0.0); vAccent = vec3(0.0); vId = 0.0; vLocal = vec2(0.0);
  bool show = vis < 0.5;
  if(vis > 0.5 && vis < 1.5) show = headless < 0.5;                   // head + visor
  if(vis > 1.5 && vis < 2.5) show = forward > 0.5 && weapon < 0.5;    // bare-hand barrel
  if(vis > 2.5) show = abs(vis - ${glf(VIS_WEAPON0 - 1)} - weapon) < 0.5; // the held weapon
  if(!show){ gl_Position = vec4(2.0, 2.0, 2.0, 1.0); return; }        // collapsed: off-clip point

  vec3 p = aPos, n = aNormal;
  if(joint > 0.5 && joint < 4.5){
    // legs: [shin/foot: knee bend, drop to the knee,] hip swing, out to the hip
    bool right = joint > 2.5;
    float ph = right ? aI2.y : aI2.x;
    if(abs(joint - 2.0) < 0.5 || abs(joint - 4.0) < 0.5){
      rotX(p, n, max(0.0, -ph) * ${glf(RIG.kneeBend)});
      p.y += ${glf(RIG.kneeY)};
    }
    rotX(p, n, ph);
    p += vec3(right ? ${glf(RIG.hipX)} : ${glf(-RIG.hipX)}, ${glf(RIG.hipY)}, 0.0);
  } else if(joint > 4.5){
    // arms: [forearm + what the hand holds: elbow bend, drop to the elbow,]
    // shoulder (the gun-hand AIMS forward; otherwise splay then swing), out
    // to the shoulder
    bool right = joint > 6.5;
    bool aims = right && forward > 0.5;
    if(abs(joint - 6.0) < 0.5 || abs(joint - 8.0) < 0.5){
      if(!aims) rotX(p, n, aI3.z);
      p.y += ${glf(RIG.elbowY)};
    }
    if(aims){
      rotX(p, n, ${glf(RIG.aim)} + aI1.w);
    } else {
      rotZ(p, n, right ? aI3.y : -aI3.y);
      rotX(p, n, (right ? aI2.w : aI2.z) - aI3.x);
    }
    p += vec3(right ? ${glf(RIG.shoulderX)} : ${glf(-RIG.shoulderX)}, ${glf(RIG.shoulderY)}, 0.0);
  }
  // root: backward lean, facing, bob / shove offsets
  rotX(p, n, aI1.y);
  rotY(p, n, aI0.z);
  p += vec3(0.0, aI1.x, aI1.z);

  vec4 clip = uVP * vec4(p, 1.0);      // ortho cameras only: w = 1
  vLocal = clip.xy;
  clip.xy = (clip.xy*0.5 + 0.5 + aI0.xy) * uTileScale - 1.0;
  gl_Position = clip;
  vN = normalize(n);
  vColor = uCol[int(colIdx(aExtra.y, aI0.w) + 0.5)];
  vAccent = uCol[int(colIdx(aExtra.z, aI0.w) + 0.5)];
  vId = aExtra.w;
}
`;
// sceneFS + the tile clip (pixel centres never sit ON the tile edge, so the
// discard cuts exactly where the CPU path's per-tile scissor does)
const rigFS = `
precision mediump float;
varying vec3 vN;
varying vec3 vColor;
varying vec3 vAccent;
varying float vId;
varying vec2 vLocal;
void main(){
  if(abs(vLocal.x) > 1.0 || abs(vLocal.y) > 1.0) discard;
  vec3 L = normalize(vec3(0.35, 0.9, 0.45));
  float ndl = max(dot(normalize(vN), L), 0.0);
  float amb = 0.35;
  float shade = amb + ndl*0.75;
  vec3 base = mix(vColor, vAccent, clamp(vN.y*0.5+0.2,0.0,1.0)*0.4);
  vec3 col = base * shade;
  gl_FragColor = vec4(col, vId);
}
`;
/* The GPU rig's mesh: every box pre-placed in its joint's frame (10 floats
   per vertex like the merged mesh: pos3 / nrm3 / extra4), in the CPU rig's
   DRAW ORDER (body, barrel, then the weapons) so depth-equal ties resolve
   identically. A box's non-uniform size never touches its normals: they are
   axis-aligned, and the CPU rig's normalize(mat3(M) * n) drops the scale the
   same way. */
function buildRigMesh(){
  const cube = makeCube();
  const data = [];
  function addBox(joint, vis, t, s, colSel, accSel, id){
    for(let v=0; v<cube.count; v++){
      data.push(t[0] + s[0]*cube.pos[v*3], t[1] + s[1]*cube.pos[v*3+1], t[2] + s[2]*cube.pos[v*3+2],
                cube.nrm[v*3], cube.nrm[v*3+1], cube.nrm[v*3+2],
                joint + 16*vis, colSel, accSel, id);
    }
  }
  RIG_BOXES.forEach((b, slot) => {
    const [colSel, accSel, id] = BODY_PART_TAGS[slot];
    const vis = (slot === 1 || slot === 2) ? VIS_HEAD : slot === 14 ? VIS_BARREL : VIS_ALWAYS;
    addBox(b.j, vis, b.t, b.s, colSel, accSel, id);
  });
  WEAPONS.forEach((w, k) => {
    // (k = 0 is the fist: no boxes) — same tags as the merged mesh's held models
    WEAPON_MODELS[w].forEach((b) =>
      addBox(J_RFORE, VIS_WEAPON0 + k - 1, [b.t[0], RIG.gripY + b.t[1], b.t[2]], b.s,
             weaponColSel(b.c, COL_ACCENT), COL_ACCENT, 0.9));
  });
  return {data: new Float32Array(data), count: data.length / 10};
}

const weaponColSel = (c, accentSel) =>
  c === "accent" ? accentSel :
  c === GUN_METAL ? COL_METAL :
  c === GUN_LIGHT ? COL_LIGHT :
  c === GUN_WOOD  ? COL_WOOD  : COL_DARK;
function buildMergedMesh(){

/* GPU PROBE (`?gpuprobe`): which part of a frame does the GPU pay for?

   `?perf` times the CPU side only, and on a GPU-bound machine the CPU side is
   ~1 ms of a 30 ms frame. But a GPU-bound frame loop is its own GPU timer:
   the browser hands out the next animation frame at the pace the GPU finishes
   the previous one, so the mean frame PERIOD tracks the GPU frame time
   (floored at the display's vsync). The probe exploits that — a knockout
   experiment, no timer-query extension needed:

     it wraps `frameRender`, and for ~2 s per configuration REWRITES the
     command stream before the renderer sees it, stripping one class of work
     (the backdrop, the TV static, the cached floor + walls, big rects, the
     robots, text, ... down to "clear only"), and measures the frame period.
     period(baseline) - period(knockout) = what that class costs the GPU.

   Stand still in a representative spot and let it run (2 rounds, baseline
   re-measured between them so thermal drift shows). The result table lands
   on screen, in the console, on the clipboard (best effort) and in
   `window.__gpuProbe`. The game keeps simulating; only what is DRAWN changes.

   The stream is filtered with the renderer's own OP_ARGS arity table, so the
   probe needs no knowledge of the ops it does not touch. */

const OP_CLEAR = 0, OP_RECT = 1, OP_TEXT = 6, OP_SAVE = 7, OP_RESTORE = 8,
      OP_SCALE = 12, OP_ROBOT = 11, OP_SHOGGOTH = 13, OP_POSTFX = 14,
      OP_PIX_BEGIN = 15, OP_PIX_END = 16, OP_STATIC_REF = 23, OP_BACKDROP = 24;
const POSTFX_TV_STATIC = 13;

const SETTLE_MS = 500;   // ignored after each switch (pipeline drains, caches settle)
const MEASURE_MS = 1700; // measured per configuration per round
const ROUNDS = 2;
const BIG_RECT = 0.25;   // a rect covering >= this share of the screen is "big"

// name, what it strips. `drop(op, cmds, i, ctx)` -> true = strip this op.
const CONFIGS = [
  { name: "baseline", note: "the full frame", drop: () => false },
  { name: "no backdrop", note: "op BACKDROP (the neon void, 1 opaque full-screen quad)",
    drop: (op) => op === OP_BACKDROP },
  { name: "no tv static", note: "POSTFX 13 (1 blended full-screen quad)",
    drop: (op, c, i) => op === OP_POSTFX && (c[i] | 0) === POSTFX_TV_STATIC },
  { name: "no postfx", note: "every POSTFX (scene FBO + post pass, when one is on)",
    drop: (op) => op === OP_POSTFX },
  { name: "no static geo", note: "STATIC_REF (the cached floor tiles + walls)",
    drop: (op) => op === OP_STATIC_REF },
  { name: "no big rects", note: "RECTs covering >= 25% of the screen (fades, washes, floor fills)",
    drop: (op, c, i, ctx) => op === OP_RECT && ctx.bigRect },
  { name: "no robots", note: "ROBOT + SHOGGOTH (sprite passes + their quads)",
    drop: (op) => op === OP_ROBOT || op === OP_SHOGGOTH },
  { name: "no text", note: "TEXT", drop: (op) => op === OP_TEXT },
  { name: "clear only", note: "nothing but the CLEAR: the floor cost of presenting this canvas",
    drop: (op) => op !== OP_CLEAR },
];

export function wrapGpuProbe(frameRender, canvas, opArgs, gpuName) {
  const order = [];
  for (let r = 0; r < ROUNDS; r++) {
    for (let k = 0; k < CONFIGS.length; k++) order.push(k);
    order.push(0); // baseline again: drift check
  }
  const samples = CONFIGS.map(() => []);      // frame periods (ms) per config
  const baselineRuns = [];                    // mean period of each baseline pass, in order
  let step = -1, stepStart = 0, lastT = 0, done = false, runPeriods = [];
  let bigRectLayers = 0, bigRectFrames = 0;   // baseline only: screen-covering rect overdraw
  let out = new Float32Array(1 << 16);

  const panel = document.createElement("pre");
  panel.style.cssText = "position:fixed;left:8px;top:8px;margin:0;padding:8px 10px;z-index:99;" +
    "font:12px/1.35 monospace;color:#9ff;background:rgba(0,0,0,.82);border:1px solid #299;" +
    "pointer-events:none;white-space:pre;max-height:95vh;overflow:hidden";
  document.body.appendChild(panel);
  panel.textContent = "GPU PROBE — get to a representative spot and STAND STILL; starting in 3 s…";
  const startAt = performance.now() + 3000;

  const mean = (a) => a.reduce((s, v) => s + v, 0) / (a.length || 1);
  const median = (a) => { const s = a.slice().sort((x, y) => x - y); return s.length ? s[s.length >> 1] : 0; };

  function filter(cmds, cfg, measureRects) {
    if (out.length < cmds.length) out = new Float32Array(cmds.length * 2);
    const frameArea = Math.max(1, canvas.clientWidth * canvas.clientHeight);
    const ctx = { bigRect: false };
    const scales = []; let area = 1, groups = 0, o = 0, i = 0, layers = 0;
    const n = cmds.length;
    while (i < n) {
      const op = cmds[i], argc = opArgs[op];
      if (argc === undefined) break; // corrupt stream: hand the rest over untouched
      const a = i + 1;
      // just enough transform tracking to know a rect's SCREEN area
      if (op === OP_SAVE) scales.push(area);
      else if (op === OP_RESTORE) { if (scales.length) area = scales.pop(); }
      else if (op === OP_SCALE) area *= Math.abs(cmds[a] * cmds[a + 1]);
      else if (op === OP_PIX_BEGIN) groups++;
      else if (op === OP_PIX_END) groups = Math.max(0, groups - 1);
      ctx.bigRect = false;
      if (op === OP_RECT && groups === 0) {
        const share = Math.abs(cmds[a + 2] * cmds[a + 3]) * area / frameArea;
        ctx.bigRect = share >= BIG_RECT;
        if (measureRects && ctx.bigRect) layers += Math.min(1, share);
      }
      if (!cfg.drop(op, cmds, a, ctx)) { out.set(cmds.subarray(i, a + argc), o); o += 1 + argc; }
      i = a + argc;
    }
    if (i < n) { out.set(cmds.subarray(i), o); o += n - i; }
    if (measureRects) { bigRectLayers += layers; bigRectFrames++; }
    return out.subarray(0, o);
  }

  function report() {
    const base = mean(baselineRuns);
    const rows = CONFIGS.map((c, k) => {
      const p = mean(samples[k]);
      return { config: c.name, periodMs: +p.toFixed(2), medianMs: +median(samples[k]).toFixed(2),
               fps: +(1000 / p).toFixed(1), savesMs: +(base - p).toFixed(2), frames: samples[k].length, note: c.note };
    });
    const result = {
      gpu: gpuName, dpr: window.devicePixelRatio,
      canvas: { w: canvas.width, h: canvas.height, cssW: canvas.clientWidth, cssH: canvas.clientHeight },
      url: location.search,
      baselineRunsMs: baselineRuns.map((v) => +v.toFixed(2)),
      bigRectLayersPerFrame: +(bigRectLayers / Math.max(1, bigRectFrames)).toFixed(2),
      rows,
    };
    window.__gpuProbe = result;
    const pad = (s, n) => String(s).padEnd(n), lpad = (s, n) => String(s).padStart(n);
    const lines = [
      `GPU PROBE — ${gpuName}`,
      `canvas ${canvas.width}x${canvas.height} (dpr ${window.devicePixelRatio}) ${location.search}`,
      `baseline passes (ms, in order — drift check): ${result.baselineRunsMs.join("  ")}`,
      `big-rect overdraw in the baseline: ${result.bigRectLayersPerFrame} screens/frame`,
      "",
      `${pad("config", 15)}${lpad("period", 8)}${lpad("median", 8)}${lpad("fps", 7)}${lpad("saves", 8)}`,
      ...rows.map((r) => `${pad(r.config, 15)}${lpad(r.periodMs.toFixed(1), 8)}${lpad(r.medianMs.toFixed(1), 8)}` +
        `${lpad(r.fps.toFixed(0), 7)}${lpad(r.savesMs.toFixed(1), 8)}   ${r.note}`),
      "",
      "(a period near 16.7 = vsync floor: the GPU had headroom in that config)",
      "copied to the clipboard (best effort) — also window.__gpuProbe / the console",
    ];
    panel.textContent = lines.join("\n");
    const json = JSON.stringify(result);
    console.log(lines.join("\n")); console.log(json);
    try { navigator.clipboard.writeText(json).catch(() => {}); } catch (e) { /* no clipboard */ }
  }

  return function probedFrameRender(cmds, textArena) {
    const now = performance.now();
    if (done || now < startAt) { lastT = now; return frameRender(cmds, textArena); }
    if (step < 0 || now - stepStart >= SETTLE_MS + MEASURE_MS) {
      if (step >= 0 && order[step] === 0) baselineRuns.push(mean(runPeriods));
      step++; stepStart = now; runPeriods = [];
      if (step >= order.length) { done = true; report(); return frameRender(cmds, textArena); }
      panel.textContent = `GPU PROBE — stand still… ${step + 1}/${order.length}: ${CONFIGS[order[step]].name}`;
    } else if (now - stepStart >= SETTLE_MS && lastT > 0) {
      const dt = now - lastT;
      if (dt < 250) { samples[order[step]].push(dt); runPeriods.push(dt); } // (tab-switch stalls excluded)
    }
    lastT = now;
    const k = order[step];
    return frameRender(filter(cmds, CONFIGS[k], k === 0), textArena);
  };
}

// Headless acceptance test for the FOLDED TV STATIC — a standalone script
// like composite-coherence.js, not a Playwright spec:
//
//   cd tests/e2e && bun grain-fold.js [baseURL=http://localhost:8098]
//
// The film grain (POSTFX 13) used to be one more alpha-blended full-screen
// quad over the finished frame. renderer.js now FOLDS it into the batch
// fragment shader: every fragment that lands on the canvas is grained as it
// is written, g(c) = c*(1-k) + n*k — an affine map, which commutes with
// alpha blending, so the final pixels are the quad's (see FS in renderer.js)
// and a whole full-screen layer of fill disappears.
//
// This script proves the "same pixels" half on REAL game frames: it captures
// the command stream of a live frame, freezes the game, and renders that one
// stream three ways with a fixed noise roll —
//     QUAD  (window.__grainFold = false: the old end-of-frame quad),
//     FOLD  (the default),
//     NONE  (the stream with its POSTFX op stripped: no grain at all)
// and asserts, over every pixel of the canvas:
//   1) FOLD == QUAD to within 8-bit rounding (the quad rounds the finished
//      colour once, the fold rounds at every blend): max channel delta <= 3,
//      and only a small share of pixels off by more than 1;
//   2) the grain is really there: FOLD differs from NONE on most pixels,
//      by about as much as QUAD does (a fold that silently turned itself
//      off would pass (1) against nothing... so compare against NONE).
// Scenes: plain gameplay, the `?pixel=N` world (the premultiplied group
// composite path), and floor 0's opening dialogue (translucent slab, text,
// portraits over the scene).
const { chromium } = require('playwright');

const BASE = process.argv[2] || 'http://localhost:8098';
const SCENES = [
  ['gameplay', '/?floor=5&debug'],
  ['pixel world', '/?floor=5&debug&pixel=3'],
  ['dialogue', '/?floor=0&debug'],
];

(async () => {
  const browser = await chromium.launch({
    args: ['--no-sandbox', '--disable-setuid-sandbox', '--enable-unsafe-swiftshader', '--use-gl=angle', '--use-angle=swiftshader', '--disable-dev-shm-usage'],
  });
  let failures = 0;
  const report = (ok, msg) => { console.log((ok ? 'PASS ' : 'FAIL ') + msg); if (!ok) failures++; };

  for (const [name, url] of SCENES) {
    const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 });
    await page.addInitScript(() => {
      window.__fakeT = null;
      const orig = performance.now.bind(performance);
      performance.now = () => (window.__fakeT == null ? orig() : window.__fakeT);
      try { localStorage.setItem('om.fps_cap', '120'); } catch (e) {}
      // Tap frameRender: keep a copy of the latest frame's stream.
      let real = null;
      Object.defineProperty(window, 'frameRender', {
        configurable: true,
        set(f) { real = f; window.__realFrameRender = f; },
        get() {
          return real && function (cmds, text) {
            window.__lastFrame = { cmds: new Float32Array(cmds), text };
            return real(cmds, text);
          };
        },
      });
    });
    const errors = [];
    page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
    page.on('pageerror', (e) => errors.push(String(e)));
    await page.goto(BASE + url);
    await page.waitForFunction(() => document.getElementById('loading').style.display === 'none', null, { timeout: 30000 });
    await page.waitForTimeout(1200);
    await page.evaluate(() => { window.__fakeT = performance.now(); }); // freeze: the FPS cap now skips every engine frame
    await page.waitForTimeout(200);

    const r = await page.evaluate(() => {
      const canvas = document.getElementById('glcanvas');
      const W = canvas.width, H = canvas.height;
      const c2 = document.createElement('canvas'); c2.width = W; c2.height = H;
      const g2 = c2.getContext('2d', { willReadFrequently: true });
      const { cmds, text } = window.__lastFrame;
      const OP_ARGS = [4, 8, 9, 7, 9, 9, 8, 0, 0, 2, 1, 8, 2, 6, 5, 4, 2, 6, 5, 6, 16, 1, 0, 1, 4, 5];
      let hasStatic = false, hasBackdrop = false;
      const stripped = [];
      for (let i = 0; i < cmds.length;) {
        const op = cmds[i], n = OP_ARGS[op];
        if (op === 14 && (cmds[i + 1] | 0) === 13) hasStatic = true;
        if (op === 24) hasBackdrop = true;
        if (op !== 14) for (let k = 0; k <= n; k++) stripped.push(cmds[i + k]);
        i += 1 + n;
      }
      window.__grainOffset = [37 / 512, 211 / 512];
      function shot(stream, fold) {
        window.__grainFold = fold;
        window.__realFrameRender(stream, text);
        g2.clearRect(0, 0, W, H);
        g2.drawImage(canvas, 0, 0);
        return g2.getImageData(0, 0, W, H).data;
      }
      const quad = shot(cmds, false), fold = shot(cmds, true), none = shot(new Float32Array(stripped), true);
      function diff(a, b) {
        let max = 0, over1 = 0, any = 0, sum = 0;
        for (let p = 0; p < a.length; p += 4) {
          let m = 0;
          for (let c = 0; c < 3; c++) m = Math.max(m, Math.abs(a[p + c] - b[p + c]));
          if (m > max) max = m;
          if (m > 1) over1++;
          if (m > 0) any++;
          sum += m;
        }
        const px = a.length / 4;
        return { max, over1: over1 / px, any: any / px, mean: sum / px };
      }
      return { W, H, hasStatic, hasBackdrop, foldVsQuad: diff(fold, quad), foldVsNone: diff(fold, none), quadVsNone: diff(quad, none) };
    });

    const f = r.foldVsQuad, gN = r.foldVsNone, qN = r.quadVsNone;
    console.log(`${name}: ${r.W}x${r.H} · fold vs quad: max ${f.max}, >1 on ${(f.over1 * 100).toFixed(3)}% px, any on ${(f.any * 100).toFixed(1)}% ` +
      `· grain strength (mean delta vs no grain): fold ${gN.mean.toFixed(2)} / quad ${qN.mean.toFixed(2)}, touches ${(gN.any * 100).toFixed(0)}% px`);
    report(errors.length === 0, `${name}: no console / page errors${errors.length ? ': ' + errors.join(' | ') : ''}`);
    report(r.hasStatic && r.hasBackdrop, `${name}: the frame carries the TV static and a BACKDROP (the fold's precondition)`);
    report(f.max <= 3, `${name}: fold == quad to 8-bit rounding (max channel delta ${f.max} <= 3)`);
    report(f.over1 <= 0.02, `${name}: deltas above 1 on ${(f.over1 * 100).toFixed(3)}% of pixels (<= 2%)`);
    report(gN.any >= 0.5 && qN.mean > 0 && Math.abs(gN.mean - qN.mean) <= 0.25 * qN.mean,
      `${name}: the folded grain is there, as strong as the quad's (${gN.mean.toFixed(2)} vs ${qN.mean.toFixed(2)})`);
    await page.close();
  }

  await browser.close();
  if (failures) { console.log(`${failures} FAILED`); process.exit(1); }
  console.log('ALL PASS');
})().catch((e) => { console.error(e); process.exit(1); });
